//! Git-backed test doubles and repo-setup helpers shared across crates'
//! test suites.

use std::io::Write;
use std::path::Path;

use callisto_model::{CommandError, CommandOutput, CommandRunner};

/// A [`CommandRunner`] that runs the real `git`, for tests that read a
/// fixture repository through `callisto_model::vcs::GitAccess`. Every other program
/// succeeds with no output.
pub struct GitRunner;

impl CommandRunner for GitRunner {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
        self.run_with_env(program, args, cwd, &[])
    }

    fn run_with_env(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        env: &[(&str, &str)],
    ) -> Result<CommandOutput, CommandError> {
        if program != "git" {
            return Ok(CommandOutput {
                exit_code: Some(0),
                stdout: String::new(),
                stderr: String::new(),
            });
        }
        let output = std::process::Command::new(program)
            .args(args)
            .current_dir(cwd)
            .envs(env.iter().copied())
            .output()
            .map_err(|e| CommandError::Io {
                program: program.to_string(),
                message: e.to_string(),
            })?;
        Ok(CommandOutput {
            exit_code: output.status.code(),
            stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
            stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
        })
    }

    fn run_with_stdin(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        stdin: &[u8],
    ) -> Result<CommandOutput, CommandError> {
        if program != "git" {
            return Err(CommandError::Unsupported {
                program: program.to_string(),
                reason: "the fixture runner only pipes input to git".to_string(),
            });
        }
        let mut child = std::process::Command::new(program)
            .args(args)
            .current_dir(cwd)
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .stderr(std::process::Stdio::piped())
            .spawn()
            .map_err(|error| CommandError::Io {
                program: program.to_string(),
                message: error.to_string(),
            })?;
        child
            .stdin
            .take()
            .expect("piped stdin exists")
            .write_all(stdin)
            .map_err(|error| CommandError::Io {
                program: program.to_string(),
                message: error.to_string(),
            })?;
        let output = child.wait_with_output().map_err(|error| CommandError::Io {
            program: program.to_string(),
            message: error.to_string(),
        })?;
        Ok(CommandOutput {
            exit_code: output.status.code(),
            stdout: String::from_utf8_lossy(&output.stdout).into_owned(),
            stderr: String::from_utf8_lossy(&output.stderr).into_owned(),
        })
    }
}

/// Runs `git` with `args` in `dir`, panicking if `git` is unavailable or the
/// invocation fails. Test-only helper for building fixture repos.
pub fn run_git(dir: &Path, args: &[&str]) {
    let status = std::process::Command::new("git")
        .args(args)
        .current_dir(dir)
        .status()
        .expect("git must be installed to run this test");
    assert!(status.success(), "git {args:?} failed in {dir:?}");
}

/// Initializes `root` as a git repo with a fixed test identity
/// (`test@example.com` / `Test`), suitable for building fixture repos across
/// test suites.
///
/// Hermetic against the ambient machine's global git config: pins the
/// initial branch name (a developer machine's `init.defaultBranch` may not
/// be `main`) and disables commit/tag signing locally (a developer machine
/// may have `commit.gpgsign`/`tag.gpgsign` set globally -- under a test
/// runner that gives child processes no controlling TTY, like `cargo
/// nextest`, a real signing attempt can't prompt `pinentry` and hangs for
/// minutes instead of failing fast, or fails outright).
pub fn init_repo(root: &Path) {
    run_git(root, &["init", "-q", "-b", "main"]);
    run_git(root, &["config", "user.email", "test@example.com"]);
    run_git(root, &["config", "user.name", "Test"]);
    run_git(root, &["config", "commit.gpgsign", "false"]);
    run_git(root, &["config", "tag.gpgsign", "false"]);
    run_git(root, &["config", "gc.auto", "0"]);
    run_git(root, &["config", "maintenance.auto", "false"]);
}

#[cfg(test)]
mod tests {
    use super::*;

    /// Writes a `GIT_CONFIG_GLOBAL`-overriding config file that pins
/// The deadline for purely local git reads (`rev-parse`, `for-each-ref`, `remote -v`, `diff --cached`).
pub const LOCAL_GIT_TIMEOUT: Duration = Duration::from_secs(60);

/// Trait for executing subprocess commands.
pub trait CommandRunner: Send + Sync {
    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError>;

    /// Run a command with a hard wall-clock timeout. If the process does not
    /// exit before `timeout` elapses it is killed and
    /// [`CommandError::TimedOut`] is returned.
    ///
    /// The default implementation ignores `timeout` and delegates to [`Self::run`].
    /// Implementors that control a real subprocess should override this with an
    /// actual deadline check.
    fn run_with_timeout(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        _timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        self.run(program, args, cwd)
    }

    /// Run a child after removing selected inherited environment variables.
    /// The default fails closed: runners that spawn real subprocesses must implement filtering explicitly.
    fn run_with_timeout_env_filtered(
        &self,
        program: &str,
        _args: &[&str],
        _cwd: &Path,
        _timeout: Duration,
        removed: &[&str],
    ) -> Result<CommandOutput, CommandError> {
        if removed.is_empty() {
            return self.run_with_timeout(program, _args, _cwd, _timeout);
        }
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this command runner does not support filtering the child environment".to_string(),
        })
    }

    /// Run a child with extra environment variables, such as `GIT_INDEX_FILE` for a git command on a temporary index.
    /// Runners without an explicit child-environment implementation fail closed.
    fn run_with_env(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        env: &[(&str, &str)],
    ) -> Result<CommandOutput, CommandError> {
        if env.is_empty() {
            return self.run(program, args, cwd);
        }
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this command runner does not support a child environment".to_string(),
        })
    }

    /// Run a publisher with credentials supplied only to that child.
    /// Runners without an explicit child-environment implementation fail closed.
    fn run_with_timeout_publisher(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
        env: &[(&str, &str)],
    ) -> Result<CommandOutput, CommandError> {
        if env.is_empty() {
            return self.run_with_timeout(program, args, cwd, timeout);
        }
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this command runner does not support a publisher child environment".to_string(),
        })
    }

    /// Like [`Self::run_with_timeout`], but for an internal existence/probe
    /// check whose stderr looks like a failure on the common path (e.g.
    /// `npm view` against an unpublished package prints a 404-shaped "not
    /// found" to stderr normally) -- unlike a real, user-facing mutating
    /// command, this must not stream that noise live to the terminal, only
    /// capture it into [`CommandOutput`] for the caller to classify.
    ///
    /// Default implementation just delegates to [`Self::run_with_timeout`]
    /// (streams live); implementors doing their own live-streaming should
    /// override this to suppress it for probe calls.
    fn run_quiet(
        &self,
        program: &str,
        args: &[&str],
        cwd: &Path,
        timeout: Duration,
    ) -> Result<CommandOutput, CommandError> {
        self.run_with_timeout(program, args, cwd, timeout)
    }

    /// Like [`Self::run`], but pipes `stdin` to the child process before
    /// reading its output. Needed for subcommands with a line-oriented
    /// input protocol -- e.g. `git cat-file --batch`, which reads one
    /// object identifier per line from stdin and streams each object's
    /// contents back on stdout, letting many objects be fetched in one
    /// subprocess round trip instead of one invocation per object.
    ///
    /// The default implementation returns [`CommandError::Unsupported`]:
    /// the great majority of [`CommandRunner`] implementors in this
    /// workspace (test doubles, etc.) never pipe
    /// stdin to a child process, so they don't need to implement this --
    /// only a real subprocess-backed runner used for such a call should
    /// override it.
    fn run_with_stdin(
        &self,
        program: &str,
        _args: &[&str],
        _cwd: &Path,
        _stdin: &[u8],
    ) -> Result<CommandOutput, CommandError> {
        Err(CommandError::Unsupported {
            program: program.to_string(),
            reason: "this CommandRunner does not support piping input to the child process".to_string(),
        })
    }
}

