    let fixture = Fixture::new();
    fixture.split_origin();
    fixture.land("push.git", "HEAD");
    assert_eq!(
        fixture.observe().unwrap(),
        ProviderObservationV1::Exact {
            evidence: ProviderEvidenceV1::GitTag {
                peeled_commit: fixture.commit("HEAD"),
            },
        }
    );
}

